effect.shader:
// A curva do AM (válida de 1000 a 40000 K, e 0 para o branco puro), em mediump como no AM (o padrão dele).
mediump vec3 colorTemperatureToRGB(const in mediump float temperature) {
    mediump mat3 m = (temperature <= 6500.0) ? mat3(vec3(0.0, -2902.1955373783176, -8257.7997278925690),
                                                    vec3(0.0, 1669.5803561666639, 2575.2827530017594),
                                                    vec3(1.0, 1.3302673723350029, 1.8993753891711275)) :
                                               mat3(vec3(1745.0425298314172, 1216.6168361476490, -8257.7997278925690),
                                                    vec3(-2666.3474220535695, -2173.1012343082230, 2575.2827530017594),
                                                    vec3(0.55995389139931482, 0.70381203140554553, 1.8993753891711275));
    return mix(clamp(vec3(m[0] / (vec3(clamp(temperature, 1000.0, 40000.0)) + m[1]) + m[2]), vec3(0.0), vec3(1.0)),
               vec3(1.0), smoothstep(1000.0, 0.0, temperature));
}

void main() {
    vec4 camada = texture(inputImg, acScreenNorm);
    // A camada do AM chega pré-multiplicada EM 8 BITS (o premul do Android); no opaco, o float da textura. A leitura
    // dele é mediump.
    vec3 p = camada.a < 1.0 ? floor(camada.rgb * camada.a * 255.0 + 0.5) / 255.0 : camada.rgb;
    mediump vec4 texColor = vec4(p, camada.a);
    highp vec3 rgb = texColor.rgb;
    lowp float a = texColor.a;
    // Os uniforms do AM são mediump (os do Nova nascem highp): a conta da temperatura começa em mediump, como lá.
    mediump float temperaturaDoAm = temperature;
    mediump float intensidadeDoAm = strength;
    rgb = mix(rgb, rgb * colorTemperatureToRGB(temperaturaDoAm * 1000.0), intensidadeDoAm);
    vec3 saida = clamp(rgb, 0.0, 1.0);                            // o buffer de 8 bits do AM corta em 0 e 1
    fragColor = a > 0.0 ? vec4(min(saida / a, vec3(1.0)), a) : vec4(0.0);
}
